import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import { Slot } from './slot';
import { Slot as SlotOld } from './slot-old.scratch';
import { afterEach, it, expect, vi } from 'vitest';

// Scratch probe: proves the no-forwardedRef ref contract is byte-identical
// between the pre-change (HEAD) Slot and the working-tree Slot.
afterEach(cleanup);

const callShape = (fn: ReturnType<typeof vi.fn>) =>
  fn.mock.calls.map((c) => ({
    len: c.length,
    first: c[0] === null ? 'null' : c[0] === undefined ? 'undefined' : 'dom-node',
  }));

it.each([
  ['old (HEAD)', SlotOld],
  ['new (working tree)', Slot],
])('%s: child ref is passed through untouched when no Slot ref is given', (_label, SlotCmp) => {
  const fn = vi.fn();
  const { unmount } = render(
    <SlotCmp>
      <button ref={fn} type="button">
        hi
      </button>
    </SlotCmp>,
  );

  const btn = screen.getByRole('button');
  expect(fn).toHaveBeenCalledTimes(1);
  expect(fn.mock.calls[0][0]).toBe(btn);
  const mountShape = callShape(fn);

  unmount();
  const unmountShape = callShape(fn);

  // React 19 detaches function refs with (null, ...extra undefineds); assert first arg only.
  expect(unmountShape[unmountShape.length - 1].first).toBe('null');

  // Old and new must produce the exact same call sequences.
  if (_label.startsWith('old')) {
    globalThis.__oldShape = [mountShape, unmountShape];
  } else {
    expect([mountShape, unmountShape]).toEqual(globalThis.__oldShape);
  }
});

it.each([
  ['old (HEAD)', SlotOld],
  ['new (working tree)', Slot],
])('%s: child RefObject is attached to the node when no Slot ref is given', (_label, SlotCmp) => {
  const ref = React.createRef<HTMLButtonElement>();
  render(
    <SlotCmp>
      <button ref={ref} type="button">
        hi
      </button>
    </SlotCmp>,
  );
  expect(ref.current).toBe(screen.getByRole('button'));
});

declare global {
  // eslint-disable-next-line no-var
  var __oldShape: unknown;
}

